// AUTHORED. Bundles the exporter plugin v0.3.0: src/extract.js + code.js → dist-plugin/code.js (generated).
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const EXPORTER_DIR = dirname(fileURLToPath(import.meta.url));

export function bundleSource() {
  return (
    "// GENERATED by tools/figma-exporter/bundle.mjs — do not edit. Edit src/extract.js or code.js.\n" +
    readFileSync(join(EXPORTER_DIR, "src/extract.js"), "utf8") +
    "\n" +
    readFileSync(join(EXPORTER_DIR, "code.js"), "utf8")
  );
}

export function bundleExporter(outFile = join(EXPORTER_DIR, "dist-plugin/code.js")) {
  const out = bundleSource();
  mkdirSync(dirname(outFile), { recursive: true });
  writeFileSync(outFile, out);
  return out;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  bundleExporter();
  console.log("Bundled tools/figma-exporter/dist-plugin/code.js");
}
